1: interface PanelResizeOptions {
2:   startX: number;
3:   startWidth: number;
4:   target: HTMLElement;
5:   minWidth: number;
6:   maxWidth: () => number;
7:   onCommit: (width: number) => void;
8:   onFinish?: () => void;
9: }
10: 
11: /** Clamp one right-dock resize sample to the current window constraints. */
12: export function resizedPanelWidth(
13:   startX: number,
14:   currentX: number,
15:   startWidth: number,
16:   minWidth: number,
17:   maxWidth: number,
18: ): number {
19:   const delta = startX - currentX;
20:   return Math.min(Math.max(minWidth, maxWidth), Math.max(minWidth, startWidth + delta));
21: }
22: 
23: /**
24:  * Keep a dock resize in the host renderer even when the pointer crosses an
25:  * Electron webview. The shield owns subsequent mouse events, while the dock's
26:  * inline width is previewed directly so the whole React app does not rerender
27:  * for every raw mouse sample. React state is committed once at the end.
28:  */
29: export function startPanelResize({
30:   startX,
31:   startWidth,
32:   target,
33:   minWidth,
34:   maxWidth,
35:   onCommit,
36:   onFinish,
37: }: PanelResizeOptions): () => void {
38:   const ownerDocument = target.ownerDocument;
39:   const ownerWindow = ownerDocument.defaultView;
40:   if (!ownerWindow) return () => undefined;
41: 
42:   const shield = ownerDocument.createElement("div");
43:   shield.setAttribute("data-panel-resize-shield", "true");
44:   shield.setAttribute("aria-hidden", "true");
45:   shield.style.position = "fixed";
46:   shield.style.inset = "0";
47:   shield.style.zIndex = "2147483647";
48:   shield.style.cursor = "col-resize";
49:   shield.style.userSelect = "none";
50:   shield.style.touchAction = "none";
51:   shield.style.pointerEvents = "auto";
52:   shield.style.background = "transparent";
53: 
54:   // Electron guests can otherwise take mouse ownership away from the host
55:   // renderer mid-drag. Restore their previous inline values verbatim.
56:   const guests = Array.from(target.querySelectorAll<HTMLElement>("webview"));
57:   const guestPointerEvents = guests.map((guest) => guest.style.pointerEvents);
58:   guests.forEach((guest) => {
59:     guest.style.pointerEvents = "none";
60:   });
61: 
62:   const previousUserSelect = ownerDocument.body.style.userSelect;
63:   const previousCursor = ownerDocument.body.style.cursor;
64:   ownerDocument.body.style.userSelect = "none";
65:   ownerDocument.body.style.cursor = "col-resize";
66:   ownerDocument.body.appendChild(shield);
67: 
68:   const hasAnimationFrame = typeof ownerWindow.requestAnimationFrame === "function";
69:   const requestFrame = (callback: FrameRequestCallback): number =>
70:     hasAnimationFrame
71:       ? ownerWindow.requestAnimationFrame(callback)
72:       : ownerWindow.setTimeout(() => callback(ownerWindow.performance.now()), 16);
73:   const cancelFrame = (id: number): void => {
74:     if (hasAnimationFrame) ownerWindow.cancelAnimationFrame(id);
75:     else ownerWindow.clearTimeout(id);
76:   };
77: 
78:   let disposed = false;
79:   let pendingWidth = startWidth;
80:   let frameId: number | null = null;
81: 
82:   const applyPreview = (): void => {
83:     frameId = null;
84:     target.style.width = `${pendingWidth}px`;
85:   };
86:   const preview = (currentX: number): void => {
87:     pendingWidth = resizedPanelWidth(startX, currentX, startWidth, minWidth, maxWidth());
88:     if (frameId === null) frameId = requestFrame(applyPreview);
89:   };
90:   const flushPreview = (): void => {
91:     if (frameId !== null) cancelFrame(frameId);
92:     frameId = null;
93:     target.style.width = `${pendingWidth}px`;
94:   };
95:   const finish = (commit: boolean): void => {
96:     if (disposed) return;
97:     disposed = true;
98:     if (commit) {
99:       flushPreview();
100:     } else {
101:       if (frameId !== null) cancelFrame(frameId);
102:       frameId = null;
103:       target.style.width = `${startWidth}px`;
104:     }
105:     shield.removeEventListener("mousemove", onMove);
106:     shield.removeEventListener("mouseup", onUp);
107:     ownerWindow.removeEventListener("mouseup", onUp);
108:     ownerWindow.removeEventListener("blur", onAbort);
109:     ownerWindow.removeEventListener("pointercancel", onAbort);
110:     ownerWindow.removeEventListener("keydown", onKeyDown);
111:     if (shield.parentNode) shield.parentNode.removeChild(shield);
112:     ownerDocument.body.style.userSelect = previousUserSelect;
113:     ownerDocument.body.style.cursor = previousCursor;
114:     guests.forEach((guest, index) => {
115:       guest.style.pointerEvents = guestPointerEvents[index] ?? "";
116:     });
117:     if (commit) onCommit(pendingWidth);
118:     onFinish?.();
119:   };
120:   const onMove = (event: MouseEvent): void => preview(event.clientX);
121:   const onUp = (event: MouseEvent): void => {
122:     if (Number.isFinite(event.clientX)) preview(event.clientX);
123:     finish(true);
124:   };
125:   const onAbort = (): void => finish(true);
126:   const onKeyDown = (event: KeyboardEvent): void => {
127:     if (event.key === "Escape") finish(false);
128:   };
129: 
130:   shield.addEventListener("mousemove", onMove);
131:   shield.addEventListener("mouseup", onUp);
132:   ownerWindow.addEventListener("mouseup", onUp);
133:   ownerWindow.addEventListener("blur", onAbort);
134:   ownerWindow.addEventListener("pointercancel", onAbort);
135:   ownerWindow.addEventListener("keydown", onKeyDown);
136: 
137:   return () => finish(false);
138: }
